<script setup lang="ts">
import {ref,computed,onMounted} from 'vue';import {useRouter} from 'vue-router';import {api,media,write,notify} from '../api';import {type Entry,recipeCategories} from '../types';import Icon from '../components/Icon.vue';
const entries=ref<Entry[]>([]),loading=ref(true),error=ref(''),q=ref(''),category=ref('全部'),favorite=ref(false),sort=ref('recent'),limit=ref(24);const router=useRouter();const busy=ref('');
async function load(){error.value='';loading.value=true;try{entries.value=(await api<Entry[]>('records')).filter(x=>x.kind==='recipe')}catch(e){error.value=(e as Error).message}finally{loading.value=false}}onMounted(load);
const filtered=computed(()=>{const query=q.value.trim().toLowerCase();let list=entries.value.filter(x=>(category.value==='全部'||x.category===category.value)&&(!favorite.value||x.favorite)&&(!query||[x.name,x.notes,x.category,...x.tags,...x.ingredients.map(i=>i.name)].join(' ').toLowerCase().includes(query)));if(sort.value==='frequent')list.sort((a,b)=>b.logs.length-a.logs.length);if(sort.value==='quick')list.sort((a,b)=>(a.minutes||999999)-(b.minutes||999999));if(sort.value==='name')list.sort((a,b)=>a.name.localeCompare(b.name,'zh'));return list});
const categories=computed(()=>['全部',...new Set([...recipeCategories.filter(c=>entries.value.some(x=>x.category===c)),...entries.value.map(x=>x.category).filter(Boolean)])]);const cookCount=computed(()=>entries.value.reduce((n,x)=>n+x.logs.length,0));
async function toggle(e:Entry){if(busy.value)return;busy.value=e.id;try{const saved=await write(e.id,{revision:e.revision,action:'favorite',favorite:!e.favorite});entries.value=entries.value.map(x=>x.id===e.id?saved:x);notify(saved.favorite?'已加入拿手好菜':'已取消收藏')}catch(e){notify((e as Error).message)}finally{busy.value=''}}
function random(){const list=filtered.value;if(!list.length)return;router.push('/recipes/'+list[Math.floor(Math.random()*list.length)].id)}
</script>
<template><div class="page library"><section class="hero"><div class="hero-copy"><div class="eyebrow"><span></span> THE FAMILY COOKBOOK</div><h1>把家的味道，<br><em>一页页留住。</em></h1><p>那些吃过还想吃的菜，和厨房里的小小心得。</p><RouterLink to="/new" class="btn primary"><Icon name="plus"/>记一道新菜</RouterLink></div><div class="hero-art"><img :src="'/recipebox/kitchen.svg'" alt="餐盘、番茄与香草组成的厨房插画"><span class="art-note">made with love</span></div></section><div class="library-heading"><div><div class="eyebrow">OUR RECIPES</div><h2>我们的菜谱 <span class="count">{{entries.length}}</span></h2></div><div class="collection-meta"><span><Icon name="flame" :size="17"/>一起下厨 {{cookCount}} 次</span><button class="btn secondary" @click="random" :disabled="!filtered.length"><Icon name="shuffle"/>今天吃什么</button></div></div><div class="tools"><label class="search"><Icon name="search"/><input v-model="q" @input="limit=24" placeholder="搜菜名、食材或标签…" aria-label="搜索菜谱"><button v-if="q" class="icon-btn" aria-label="清空搜索" @click="q=''"><Icon name="close" :size="17"/></button></label><select v-model="sort" aria-label="菜谱排序"><option value="recent">最近更新</option><option value="frequent">常做的菜</option><option value="quick">用时最短</option><option value="name">菜名排序</option></select><button class="btn favorite-filter" :class="{active:favorite}" :aria-pressed="favorite" @click="favorite=!favorite;limit=24"><Icon name="heart"/>拿手好菜</button></div><div class="chip-row" aria-label="菜谱分类"><button v-for="c in categories" :key="c" class="chip" :class="{active:category===c}" :aria-pressed="category===c" @click="category=c;limit=24">{{c}}</button></div><div v-if="loading" class="empty">正在翻开菜谱…</div><div v-else-if="error" class="empty error" role="alert">{{error}}<button class="btn secondary" @click="load">重新加载</button></div><div v-else-if="!filtered.length" class="empty"><div class="empty-icon"><Icon name="book" :size="40"/></div><h3>{{entries.length?'没有找到这道菜':'家的第一道菜，从这里开始'}}</h3><p>{{entries.length?'试试其他食材，或换一个分类。':'先记下菜名，照片和做法可以慢慢补。'}}</p><RouterLink v-if="!entries.length" to="/new" class="btn primary"><Icon name="plus"/>记录第一道菜</RouterLink><button v-else class="btn secondary" @click="q='';category='全部';favorite=false">清除筛选</button></div><div v-else class="recipe-grid"><article v-for="e in filtered.slice(0,limit)" :key="e.id" class="recipe-card"><RouterLink :to="'/recipes/'+e.id" class="card-image"><img v-if="e.photoIds.length" :src="media(e.photoIds[0],true)" :alt="e.name" loading="lazy"><div v-else class="dish-placeholder"><Icon :name="e.category==='素菜'?'leaf':'book'" :size="56"/><span>等一张美味的照片</span></div><span class="category-label">{{e.category||'家常菜'}}</span></RouterLink><button class="card-heart icon-btn" :class="{liked:e.favorite}" :aria-label="(e.favorite?'取消收藏 ':'收藏 ')+e.name" :disabled="busy===e.id" @click="toggle(e)"><Icon name="heart"/></button><RouterLink :to="'/recipes/'+e.id" class="card-content"><h3>{{e.name}}</h3><p>{{e.ingredients.length?e.ingredients.slice(0,4).map(x=>x.name).join(' · '):e.notes||'好味道，值得慢慢记下'}}</p><div class="card-bottom"><span><Icon name="clock" :size="15"/>{{e.minutes?e.minutes+' 分钟':'随心慢做'}}</span><span>{{e.logs.length?'做过 '+e.logs.length+' 次':'新收录'}}</span></div></RouterLink></article><RouterLink to="/new" class="add-card"><div><Icon name="plus" :size="30"/></div><h3>下一道家的味道</h3><p>把今天的美味也记下来</p></RouterLink></div><button v-if="filtered.length>limit" class="btn secondary load-more" @click="limit+=24">再看 24 道菜</button><footer class="page-footer">每一顿家常饭，都是值得珍藏的小日子。</footer></div></template>
